#!/usr/bin/env python3
"""Merge user records from JSON, CSV, and Parquet sources.

Priority: source_a > source_b > source_c
"""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any

import pandas as pd

SOURCES = {
    "source_a": ("/data/source_a/users.json", "json"),
    "source_b": ("/data/source_b/users.csv", "csv"),
    "source_c": ("/data/source_c/users.parquet", "parquet"),
}

# All known aliases -> canonical field name.
FIELD_MAPPING = {
    "user_id": "user_id",
    "id": "user_id",
    "userid": "user_id",
    "email": "email",
    "email_address": "email",
    "full_name": "name",
    "name": "name",
    "username": "name",
    "registration_date": "created_date",
    "created_at": "created_date",
    "joined": "created_date",
}

OUTPUT_FIELDS = ["name", "email", "created_date", "status"]


def canonicalize_columns(df: pd.DataFrame) -> pd.DataFrame:
    """Rename columns using case-insensitive aliases and keep usable columns."""
    rename: dict[str, str] = {}
    for col in df.columns:
        key = str(col).strip().lower().replace(" ", "_")
        canonical = FIELD_MAPPING.get(key)
        if canonical is not None and canonical not in rename.values():
            rename[col] = canonical
    df = df.rename(columns=rename)

    # Status can be represented by several source-specific names.
    status_cols = [
        c for c in df.columns
        if str(c).strip().lower() in {"status", "is_active", "active"}
    ]
    if "status" not in df.columns and status_cols:
        df = df.rename(columns={status_cols[0]: "status"})

    return df


def normalize_date(value: Any) -> Any:
    """Convert a date-like value to YYYY-MM-DD; leave missing values as None."""
    if value is None or (not isinstance(value, (list, dict)) and pd.isna(value)):
        return None
    try:
        parsed = pd.to_datetime(value, errors="coerce")
        if pd.isna(parsed):
            return None
        return parsed.strftime("%Y-%m-%d")
    except Exception:
        return None


def normalize_status(value: Any) -> Any:
    """Normalize boolean/string status values to 'active'/'inactive'."""
    if value is None or (not isinstance(value, (list, dict)) and pd.isna(value)):
        return None
    if isinstance(value, bool):
        return "active" if value else "inactive"
    if isinstance(value, (int, float)) and value in (0, 1):
        return "active" if bool(value) else "inactive"
    text = str(value).strip()
    lowered = text.lower()
    if lowered in {"true", "1", "yes", "y", "active", "enabled"}:
        return "active"
    if lowered in {"false", "0", "no", "n", "inactive", "disabled"}:
        return "inactive"
    return text or None


def clean_value(field: str, value: Any) -> Any:
    if value is None:
        return None
    if not isinstance(value, (list, dict)) and pd.isna(value):
        return None
    if field == "user_id":
        try:
            return int(value)
        except (TypeError, ValueError):
            return None
    if field == "created_date":
        return normalize_date(value)
    if field == "status":
        return normalize_status(value)
    text = str(value).strip()
    return text or None


def load_source(name: str, path: str, kind: str) -> pd.DataFrame:
    if kind == "json":
        df = pd.read_json(path)
    elif kind == "csv":
        df = pd.read_csv(path)
    elif kind == "parquet":
        df = pd.read_parquet(path)
    else:
        raise ValueError(f"Unsupported source type: {kind}")

    df = canonicalize_columns(df)
    needed = ["user_id"] + OUTPUT_FIELDS
    for col in needed:
        if col not in df.columns:
            df[col] = None
    df = df[needed].copy()

    df["user_id"] = df["user_id"].map(lambda v: clean_value("user_id", v))
    df = df[df["user_id"].notna()].copy()
    df["user_id"] = df["user_id"].astype("int64")
    for field in OUTPUT_FIELDS:
        df[field] = df[field].map(lambda v, f=field: clean_value(f, v))

    # If a source repeats an id, its first record wins within that source.
    df = df.drop_duplicates(subset=["user_id"], keep="first")
    df["_source"] = name
    return df


def main() -> None:
    frames = [load_source(name, path, kind) for name, (path, kind) in SOURCES.items()]
    all_df = pd.concat(frames, ignore_index=True, sort=False)

    priorities = {name: i for i, name in enumerate(SOURCES)}
    all_df["_priority"] = all_df["_source"].map(priorities)

    user_ids = sorted(int(uid) for uid in all_df["user_id"].unique())

    merged_rows: list[dict[str, Any]] = []
    conflicts: list[dict[str, Any]] = []

    for user_id in user_ids:
        user_rows = all_df[all_df["user_id"] == user_id]
        row_by_source = {
            r["_source"]: r for _, r in user_rows.iterrows()
        }

        merged: dict[str, Any] = {"user_id": user_id}
        for field in OUTPUT_FIELDS:
            present: dict[str, Any] = {}
            for source in SOURCES:
                if source not in row_by_source:
                    continue
                value = row_by_source[source][field]
                if value is not None:
                    present[source] = value

            if present:
                # Highest-priority non-null value wins.
                selected_source = min(present, key=lambda s: priorities[s])
                selected = present[selected_source]
            else:
                selected = None

            merged[field] = selected

            # A conflict exists only when multiple sources provide this field
            # and their values are not all identical.
            if len(present) > 1 and len({str(v) for v in present.values()}) > 1:
                conflicts.append(
                    {
                        "user_id": user_id,
                        "field": field,
                        "values": {source: present[source] for source in SOURCES if source in present},
                        "selected": selected,
                    }
                )

        merged_rows.append(merged)

    output_df = pd.DataFrame(merged_rows, columns=["user_id"] + OUTPUT_FIELDS)
    output_df["user_id"] = output_df["user_id"].astype("int64")
    for field in ["name", "email", "created_date", "status"]:
        output_df[field] = output_df[field].astype("string")

    Path("/app").mkdir(parents=True, exist_ok=True)
    output_df.to_parquet("/app/merged_users.parquet", index=False)

    report = {"total_conflicts": len(conflicts), "conflicts": conflicts}
    with open("/app/conflicts.json", "w", encoding="utf-8") as fh:
        json.dump(report, fh, indent=2, ensure_ascii=False)
        fh.write("\n")

    print(f"Wrote {len(output_df)} users to /app/merged_users.parquet")
    print(f"Wrote {len(conflicts)} conflicts to /app/conflicts.json")


if __name__ == "__main__":
    main()
